def pick_addr(url, cc=None, rc=None):
    # Simplified address picker – you can keep your full version
    return {
        "address1": "123 Main St",
        "city": "New York",
        "postalCode": "10001",
        "zoneCode": "NY",
        "countryCode": "US",
        "phone": "1234567890"
    }

def parse_proxy(proxy_str):
    if not proxy_str:
        return None
    parts = proxy_str.split(':')
    if len(parts) == 2:
        return f"http://{parts[0]}:{parts[1]}"
    elif len(parts) == 4:
        return f"http://{parts[2]}:{parts[3]}@{parts[0]}:{parts[1]}"
    return None

def extract_between(text, start, end):
    try:
        if start in text:
            parts = text.split(start, 1)
            if len(parts) > 1 and end in parts[1]:
                return parts[1].split(end, 1)[0]
    except:
        pass
    return None

def is_captcha_required(response_text):
    if not response_text:
        return False
    indicators = ['CAPTCHA_REQUIRED', 'captcha required', 'hcaptcha']
    for ind in indicators:
        if ind.upper() in response_text.upper():
            return True
    return False

class Utils:
    @staticmethod
    def get_random_name():
        first = ["James", "John", "Robert", "Michael", "William", "David", "Mary", "Patricia"]
        last = ["Smith", "Johnson", "Williams", "Brown", "Jones", "Garcia", "Miller", "Davis"]
        return random.choice(first), random.choice(last)
    @staticmethod
    def generate_email(first, last):
        domains = ["gmail.com", "yahoo.com", "outlook.com"]
        return f"{first.lower()}.{last.lower()}@{random.choice(domains)}"

async def make_graphql_request(session, graphql_url, params, headers, json_data):
    try:
        response = await session.post(graphql_url, params=params, headers=headers, json=json_data)
        resp_text = await response.text()
        return response, resp_text
    except Exception as e:
        return None, str(e)

async def fetch_products(domain, proxy_str=None):
    try:
        domain = domain if domain.startswith('http') else f'https://{domain}'
        proxy = parse_proxy(proxy_str) if proxy_str else None
        connector = aiohttp.TCPConnector(ssl=False)
        async with aiohttp.ClientSession(connector=connector) as session:
            async with session.get(f"{domain}/products.json", proxy=proxy, timeout=10) as resp:
                if resp.status != 200:
                    return False, f"HTTP {resp.status}"
                data = await resp.json()
                products = data.get('products', [])
                min_price = float('inf')
                min_product = None
                for product in products:
                    for variant in product.get('variants', []):
                        if not variant.get('available', True):
                            continue
                        try:
                            price = float(variant.get('price', 0))
                            if price < min_price:
                                min_price = price
                                min_product = {
                                    'variant_id': str(variant['id']),
                                    'price': f"{price:.2f}",
                                    'currency': 'USD'
                                }
                        except:
                            continue
                if min_product:
                    return min_product
                return False, "No available variants"
    except Exception as e:
        return False, str(e)

